import * as React from "react"
import { Link, useLocation } from "react-router-dom"
import { 
  LayoutDashboard, 
  Wallet, 
  ArrowUpRight, 
  ArrowDownLeft, 
  PieChart, 
  Settings, 
  LogOut,
  ChevronLeft,
  ChevronRight,
  Plus
} from "lucide-react"
import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import { Separator } from "@/components/ui/separator"
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "@/components/ui/tooltip"

interface SidebarItem {
  title: string
  href: string
  icon: React.ElementType
}

const sidebarItems: SidebarItem[] = [
  { title: "Tableau de bord", href: "/dashboard", icon: LayoutDashboard },
  { title: "Transactions", href: "/transactions", icon: Wallet },
  { title: "Revenus", href: "/income", icon: ArrowUpRight },
  { title: "Dépenses", href: "/expenses", icon: ArrowDownLeft },
  { title: "Analyses", href: "/analytics", icon: PieChart },
  { title: "Paramètres", href: "/settings", icon: Settings },
]

export function DashboardSidebar() {
  const [isCollapsed, setIsCollapsed] = React.useState(false)
  const location = useLocation()

  return (
    <TooltipProvider delayDuration={0}>
      <div 
        className={cn(
          "relative flex flex-col h-screen bg-sidebar border-r border-sidebar-border transition-all duration-300 ease-in-out",
          isCollapsed ? "w-20" : "w-64"
        )}
      >
        {/* Logo Section */}
        <div className="flex items-center h-16 px-6 mb-4">
          <div className="flex items-center gap-3">
            <div className="flex items-center justify-center w-8 h-8 rounded-lg bg-sidebar-primary text-sidebar-primary-foreground">
              <Wallet className="w-5 h-5" />
            </div>
            {!isCollapsed && (
              <span className="text-xl font-bold tracking-tight text-sidebar-foreground">
                KashFlow
              </span>
            )}
          </div>
        </div>

        {/* Action Button */}
        <div className="px-4 mb-6">
          {isCollapsed ? (
             <Tooltip>
                <TooltipTrigger asChild>
                  <Button size="icon" className="w-full h-10 rounded-xl bg-sidebar-primary text-sidebar-primary-foreground">
                    <Plus className="w-5 h-5" />
                  </Button>
                </TooltipTrigger>
                <TooltipContent side="right">Nouvelle Transaction</TooltipContent>
             </Tooltip>
          ) : (
            <Button className="w-full h-10 gap-2 rounded-xl bg-sidebar-primary text-sidebar-primary-foreground">
              <Plus className="w-4 h-4" />
              <span>Nouvelle Transaction</span>
            </Button>
          )}
        </div>

        <Separator className="mx-4 mb-6 opacity-50" />

        {/* Navigation Items */}
        <nav className="flex-1 px-3 space-y-1 overflow-y-auto custom-scrollbar">
          {sidebarItems.map((item) => {
            const isActive = location.pathname === item.href
            return (
              <Tooltip key={item.href}>
                <TooltipTrigger asChild>
                  <Link
                    to={item.href}
                    className={cn(
                      "flex items-center gap-3 px-3 py-2.5 rounded-lg transition-colors group relative",
                      isActive 
                        ? "bg-sidebar-accent text-sidebar-accent-foreground font-medium" 
                        : "text-muted-foreground hover:bg-sidebar-accent/50 hover:text-sidebar-foreground"
                    )}
                  >
                    <item.icon className={cn(
                      "w-5 h-5 shrink-0",
                      isActive ? "text-sidebar-primary" : "group-hover:text-sidebar-foreground"
                    )} />
                    {!isCollapsed && <span className="truncate">{item.title}</span>}
                    {isActive && !isCollapsed && (
                      <div className="absolute left-0 w-1 h-6 rounded-full bg-sidebar-primary" />
                    )}
                  </Link>
                </TooltipTrigger>
                {isCollapsed && (
                  <TooltipContent side="right">
                    {item.title}
                  </TooltipContent>
                )}
              </Tooltip>
            )
          })}
        </nav>

        <Separator className="mx-4 mt-6 opacity-50" />

        {/* User / Footer Section */}
        <div className="p-4 mt-auto">
          <Tooltip>
            <TooltipTrigger asChild>
              <button className={cn(
                "flex items-center w-full gap-3 p-2 transition-colors rounded-lg hover:bg-sidebar-accent group",
                isCollapsed ? "justify-center" : ""
              )}>
                <div className="w-8 h-8 rounded-full bg-muted flex items-center justify-center shrink-0">
                  <span className="text-xs font-bold">JD</span>
                </div>
                {!isCollapsed && (
                  <div className="flex flex-col items-start overflow-hidden text-left">
                    <span className="w-full text-sm font-medium truncate">Jean Dupont</span>
                    <span className="w-full text-xs truncate text-muted-foreground">jean@example.com</span>
                  </div>
                )}
                {!isCollapsed && (
                  <LogOut className="w-4 h-4 ml-auto text-muted-foreground group-hover:text-destructive" />
                )}
              </button>
            </TooltipTrigger>
            {isCollapsed && (
              <TooltipContent side="right">Déconnexion</TooltipContent>
            )}
          </Tooltip>
        </div>

        {/* Toggle Sidebar Button */}
        <button
          onClick={() => setIsCollapsed(!isCollapsed)}
          className="absolute flex items-center justify-center w-6 h-6 transition-colors border rounded-full -right-3 top-20 bg-background border-sidebar-border hover:bg-accent text-sidebar-foreground"
        >
          {isCollapsed ? <ChevronRight className="w-3.5 h-3.5" /> : <ChevronLeft className="w-3.5 h-3.5" />}
        </button>
      </div>
    </TooltipProvider>
  )
}

